  @const OCTAVE = 1200  @ 473
  @const REACH_TOL = 1e-9  @ 476
  @const weights = {}  @ 589
  @const MIDI_NAMES = { 'C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', '...  @ 735

# Private functions
  -- Temperament presets
  @fn computeOctaveStep(stepNames, n)  @ 18-24
      -- octaveStep: first step whose label reads as the next octave's C. Scans from
      -- the end for the last non-C name; nameless scale → bump at period (n+1).
  @fn octaveLabel(o)  @ 28-30
      -- A negative octave renders as its magnitude, for the caller to tint — the
      -- sign costs no column. See docs/tuning.md § Display.
  @fn octaveFieldWidth(temper)  @ 34-39
      -- octaveFieldWidth: char width of the octave field, sized on the octave
      -- numbers at both ends of the range the root opens. See docs/tuning.md § Display.
  @fn computeRootCents(temper)  @ 43-46
      -- rootCents: where the scale's unison sits in sound, given the root's four
      -- authored fields. See docs/tuning.md § The root.
  @fn computeCellWidth(temper)  @ 49-58
      -- cellWidth: widest step label + the octave field; see docs/tuning.md § Display.
  @fn restateOnUnison(temper)  @ 102-106
      -- The root's step is gone: restate it on the unison, at the rootCents standing before the
      -- edit — the same tuning, written at the one step every scale keeps.
  @fn edo(n, names)  @ 140-149
  -- Scala import
  -- Generators
  @fn gcd(a, b)  @ 313
  @fn combinations(n, k)  @ 316-324
      -- Every k-subset of 1..n as a list of 1-based index lists.
  @fn primeFactorsBelow(n, limit)  @ 355-365
      -- Check if every prime factor of the odd `n` is at or below `limit`.
  @fn reduceCents(c, period)  @ 387-389
      -- Reduce a cents value into [0, period).
  @fn asRatio(token)  @ 391-396
  @fn stackRatio(gn, gd, pn, pd, k)  @ 401-412
  @fn stepSpectrum(g, p, n)  @ 416-430
      -- Adjacent step sizes (incl. the wrap step) of an n-note chain of `g`
      -- reduced into `p`: {cents, count} per distinct size, large first.
  -- Coordinate conversions
  -- Targets
  @fn addOddFactors(n, coords, sign)  @ 560-571
      -- The odd primes of `n` accumulated into `coords` at `sign`. Twos are divided
      -- out first; whatever survives trial division past sqrt(n) is itself a prime.
  @fn weight(prime)  @ 590-594
  @fn coordKey(coords)  @ 617-626
      -- Coords fix a ratio up to the octave, so they identify a move outright: same coords,
      -- same reduced cents. Sorted, so a temper's two spellings of one move key alike.
  @fn gapTo(seat, cents)  @ 666-668
      -- The gap from a seat to a point of the octave-reduced line, signed and reduced so a
      -- point below the seat reads as a descent, not an ascent; shortlist and seat both use it.
  @fn seatOf(notation, note)  @ 672-677
      -- A note's own step: where it seats, and how far its window reaches either side.
      -- The shortlist, the reach and the root are all measured off it.

# Public API (tuning.*)
  @api tuning.scalaPitch(token)  @ 61-79
      @contract  token → cents or nil: n/d, int, '.'=cents, n\m, n\m<equave> step (equave dflt 2/1).  @ 60
  @api tuning.derive(temper)  @ 82-98
      @contract  pitches→cents, periodPitch→period; stamps root/octave/cell fields. Pure; returns temper.  @ 81
  @api tuning.sortSteps(temper)  @ 109-122
      @contract  sort (pitches, stepNames) ascending by compiled cents, rootStep riding with its step  @ 108
  @api tuning.removeStep(temper, i)  @ 125-131
      @contract  drop step i, the root following the step it names; a root on i restates on the unison  @ 124
  @api tuning.unrooted(temper)  @ 134-138
      @contract  copy with the four root fields dropped and stamps refreshed at the default root  @ 133
  @api tuning.findTemper(name, userLib)  @ 174-177
      @contract  userLib first, then presets; nil when unknown to both; '12EDO' resolves via presets  @ 173
  @api tuning.parseScalaPitches(text)  @ 183-190
      -- Lenient: every non-blank, non-'!' line is a pitch token. Drives paste + the
      -- import Create button (which re-parses the box after any manual edits).
  @api tuning.parseScalaFile(text)  @ 194-208
      -- Strict .scl: drop '!' comment lines, then [description, count, pitch x count].
      -- Returns pitch tokens + description (suggested name) for the Scala load path.
  @api tuning.scalaToTemper(pitchLines, name)  @ 212-230
      -- Bridge Scala's convention (unison implicit, period last) to Continuum's
      -- (step 1 = 1/1, period separate): prepend unison, split off final as period.
  @api tuning.edoDegrees(spec, mode)  @ 236-253
      -- Equal-division subset spec -> ascending degrees; largest is the period.
      -- 'relative': cumulative step counts. 'absolute': sorted+deduped. nil on bad token.
  @api tuning.degreesToSpec(degrees, mode)  @ 257-262
      -- Inverse of edoDegrees: render a degree list back as a spec string in `mode`.
      -- Lets a mode switch convert the in-flight pattern rather than reset it.
  @api tuning.genEqual(degrees, interval)  @ 266-272
      -- N-equal-divisions of `interval` subset to `degrees`; tokens are intensional
      -- (d\D<equave>, suffix omitted for octave). Base 0 implicit; last degree = period.
  @api tuning.genHarmonics(lo, hi)  @ 276-280
      -- Harmonic-series segment lo..hi: ratios m/lo rooted on the low harmonic, the
      -- top (hi/lo) the period.
  @api tuning.genSubharmonics(lo, hi)  @ 283-287
      -- Subharmonic (utonal) segment lo..hi: ratios hi/m ascending, top the period.
  @api tuning.parseChord(spec)  @ 291-300
      -- Colon/space-separated extended ratio (e.g. '4:5:6:7') -> positive integers,
      -- at least two. nil + message otherwise.
  @api tuning.genChord(members, invert)  @ 304-311
      -- Enumerate a chord as a scale rooted on its first note. otonal: ci/c1.
      -- inverted (utonal): ck/c(k+1-i). The last member is the period either way.
  @api tuning.genCPS(factors, k, equave)  @ 328-352
      -- Combination product set: every k-subset's product, rooted on the smallest
      -- product (so 1/1 is always present) and reduced into the equave; ascending.
  @api tuning.genDiamond(oddLimit, primeLimit)  @ 369-384
      -- N-odd-limit tonality diamond: coprime odd pairs to `oddLimit`, reduced into the
      -- octave; `primeLimit` filters larger primes. See design/adaptive-tuning.md § The diamond.
  @api tuning.genRank2(generator, period, size, up)  @ 434-453
      -- Rank-2 scale: stack the generator `up` above and `size-1-up` below 1/1,
      -- reduce into period, sort. up = mode. Exact ratios if inputs rational, else cents.
  @api tuning.mosInfo(generator, period, n)  @ 456-460
      @contract  {isMos, large, small} for an n-note chain; large/small are L/s step counts when isMos  @ 455
  @api tuning.nextMosSize(generator, period, fromN, dir)  @ 463-471
      @contract  next MOS size (two step sizes) from fromN, stepping dir (+/-1); nil past the cap  @ 462
  @api tuning.midiToStep(temper, midi, detune)  @ 482-501
      @contract  detune optional (defaults 0); snaps to nearest scale point including the period boundary (rounds up to step 1 of next octave)  @ 480
      @contract  returned octave is period-index + temper.octaveBase (at the default root, C-1 → -1)  @ 481
  @api tuning.stepToMidi(temper, step, octave)  @ 504-520
      @contract  wraps out-of-range step by adjusting octave; clamps midi to 0..127 by folding overflow into detune (never silently drops)  @ 503
  @api tuning.snap(temper, midi, detune)  @ 522-524
  @api tuning.stepClass(temper, midi, detune)  @ 529-532
      -- The step a note is written on, taken modulo the octave the score quotients
      -- out. See design/adaptive-tuning.md § The model.
      @contract  the note's written seat reduced into the octave; an octave apart answers alike  @ 528
  @api tuning.stepWindow(temper, step)  @ 535-541
      @contract  half-gaps in cents to steps below/above `step`; both positive, wraps the period  @ 534
  @api tuning.transposeStep(temper, midi, detune, n)  @ 544-547
      @contract  moves by n scale steps under temper, carrying the octave; n may be negative  @ 543
  @api tuning.stepsBetween(temper, aMidi, aDetune, bMidi, bDetune)  @ 550-554
      @contract  signed count of whole temper steps from note a to note b, each snapped to nearest step  @ 549
  @api tuning.coords(token)  @ 576-586
      -- Numerator and denominator are factorised apart and their exponents subtracted,
      -- so 6/4 and 3/2 read alike and a prime on both sides cancels rather than sitting at zero.
      @contract  ratio token -> {[oddPrime]=exponent}, prime 2 divided out; nil for cents or n\m  @ 575
  @api tuning.height(coords)  @ 599-605
      -- Read off the coords, so an unreduced token costs the interval it sounds, not its terms.
      -- See design/adaptive-ji.md § What makes the candidate set finite.
      @contract  coords → the octave-free Tenney height of the ratio they name: Σ |exponent| × log₂ p  @ 598
  @api tuning.isTarget(temper)  @ 608-613
      @contract  true when every pitch of `temper` is a ratio, so its points carry coords to score  @ 607
  @api tuning.moves(temper)  @ 634-662
      -- A move set read as intervals from its unison, per design/adaptive-ji.md § Where a move
      -- set comes from; an inversion carries the same height, so it sorts beside the move it inverts.
  @api tuning.shortlist(notation, target, keyStep, note, widen)  @ 684-718
      -- The only place the notation and the target meet. See design/adaptive-tuning.md
      -- § What the solver takes for why the line is reduced into the octave.
      @contract  candidates {cents, coords, strain} for the target's points inside the note's step window  @ 681
      @contract  strain is the point's gap over the window half it lies in; nearest first  @ 682
      @contract  widen: where the window holds nothing, the nearest points instead, at strain past 1  @ 683
  @api tuning.seat(notation, note, cents)  @ 723-729
      -- The shortlist's fold in reverse: a point the strand took, in the register of one
      -- of the notes that writes it, the note's own step seat being what the window was measured off.
      @contract  (pitch, detune) for `cents` placed in the octave nearest the note's seat  @ 722
  -- Display
  @api tuning.midiName(pitch)  @ 738-740
      @contract  MIDI number → untempered twelve-name spelling (0 → 'C-1', 60 → 'C4')  @ 737
  @api tuning.stepToParts(temper, step, octave)  @ 743-748
      @contract  (note, octaveLabel=|octave|, negative); name or degree+'-'; octave+1 at octaveStep  @ 742

